const wc = $('When Called').first().json;
const key = ((($('Get Anthropic Key').first() || {}).json || {}).key || '').toString().trim();
const ra = (($('Resolve Agent').first() || {}).json) || {};
const up = $json || {};
let fileMap = Array.isArray(up.file_map) ? up.file_map.slice() : [];
fileMap.sort(function(a,b){ return (Number(a.order||0)) - (Number(b.order||0)); });
const content = [];
for (const f of fileMap) { if (f && f.file_id) content.push({ type: 'image', source: { type: 'file', file_id: f.file_id } }); }
content.push({ type: 'text', text: String(wc.user_message || '') });
const warnings = Array.isArray(up.warnings) ? up.warnings.slice() : [];
const message_body_json = JSON.stringify({ events: [{ type: 'user.message', content: content }] });
return [{ json: {
  key: key,
  agent_id: ra.agent_id || '',
  model_id: ra.model_id || '',
  environment_id: ra.environment_id || '',
  file_map_json: JSON.stringify(fileMap),
  warnings_json: JSON.stringify(warnings),
  message_body_json: message_body_json,
  impact: wc.impact || '__default__',
  clickup_task_id: wc.clickup_task_id || '',
  caller_user_id: wc.caller_user_id || '',
  process_type: wc.process_type || '',
  triggered_by: wc.triggered_by || 'explicit_mention',
  invocation_type: wc.invocation_type || 'explicit'
} }];

const bs = $('Build Setup').first().json;
const sess = ($('Create Session').first() || {}).json || {};
const SOFT_DEADLINE_MS = 840000;
return [{ json: {
  session_id: sess.id || '',
  anthropic_key: bs.key,
  file_map_json: bs.file_map_json,
  deadline_epoch: Date.now() + SOFT_DEADLINE_MS,
  tool_round: 0,
  images_json: '[]',
  warnings_json: bs.warnings_json,
  agent_id: bs.agent_id,
  model_id: bs.model_id,
  impact: bs.impact,
  clickup_task_id: bs.clickup_task_id,
  caller_user_id: bs.caller_user_id,
  process_type: bs.process_type,
  triggered_by: bs.triggered_by,
  invocation_type: bs.invocation_type
} }];

const wc = $('When Called').first().json;
const e = $json || {};
const err = (e.error && (e.error.message || e.error)) || e.message || JSON.stringify(e).slice(0,300);
return [{ json: {
  status: 'failed', output_message: '', files: [], file_ids: [], usd_cost: null, usd_cost_stub: true,
  session_usage: {}, duration_seconds: null, web_search_count: 0, model_used: '', agent_id: '', session_id: '',
  impact: wc.impact || '', clickup_task_id: wc.clickup_task_id || '',
  warnings: [{ source: 'managed-agents/session-create-failed', err: String(err).slice(0,400), severity: 'CRITICAL' }],
  failure_kind: 'create', outcome: 'create_failed'
} }];

const wc = $('When Called').first().json;
const sess = ($('Create Session').first() || {}).json || {};
const e = $json || {};
const err = (e.error && (e.error.message || e.error)) || e.message || JSON.stringify(e).slice(0,300);
return [{ json: {
  status: 'failed', output_message: '', files: [], file_ids: [], usd_cost: null, usd_cost_stub: true,
  session_usage: {}, duration_seconds: null, web_search_count: 0, model_used: '', agent_id: '', session_id: sess.id || '',
  impact: wc.impact || '', clickup_task_id: wc.clickup_task_id || '',
  warnings: [{ source: 'managed-agents/session-send-failed', err: String(err).slice(0,400), severity: 'CRITICAL' }],
  failure_kind: 'send', outcome: 'send_failed'
} }];

const st = $json;
const KEY = st.anthropic_key;
const SESSION = st.session_id;
const deadlineEpoch = Number(st.deadline_epoch) || (Date.now() + 840000);
const toolRound = Number(st.tool_round || 0);
const MAX_TOOL_ROUNDS = 12;
const POLL_INTERVAL_MS = 3000;
const MAX_CONSEC_ERRORS = 5;
const BASE = 'https://api.anthropic.com';
const BOTH = 'managed-agents-2026-04-01,files-api-2025-04-14';
const httpRequest = this.helpers.httpRequest;
const headers = { 'x-api-key': KEY, 'anthropic-version': '2023-06-01', 'anthropic-beta': BOTH };
const sleep = function(ms){ return new Promise(function(r){ setTimeout(r, ms); }); };
const remaining = function(){ return deadlineEpoch - Date.now(); };
async function getEvents(){
  const res = await httpRequest({ method: 'GET', url: BASE + '/v1/sessions/' + SESSION + '/events', headers: headers, json: true, returnFullResponse: true, timeout: 20000 });
  const body = res.body || {};
  return Array.isArray(body.data) ? body.data : [];
}
async function getStatus(){
  const res = await httpRequest({ method: 'GET', url: BASE + '/v1/sessions/' + SESSION, headers: headers, json: true, returnFullResponse: true, timeout: 20000 });
  return res.body || {};
}
function analyze(events){
  let lastUserIdx = -1;
  for (let i = 0; i < events.length; i++){ const t = events[i].type; if (t === 'user.message' || t === 'user.custom_tool_result') lastUserIdx = i; }
  const answered = {};
  for (const e of events){ if (e.type === 'user.custom_tool_result' && e.custom_tool_use_id) answered[e.custom_tool_use_id] = true; }
  const pending = [];
  for (const e of events){ if (e.type === 'agent.custom_tool_use' && !answered[e.id]) pending.push(e); }
  let agentRepliedAfter = false, lastAgentMsg = null;
  for (let i = 0; i < events.length; i++){ if (events[i].type === 'agent.message'){ lastAgentMsg = events[i]; if (i > lastUserIdx) agentRepliedAfter = true; } }
  let sessionError = null;
  for (const e of events){ const t = e.type || ''; if (t === 'session.error' || (t.indexOf('error') >= 0 && e.error)) sessionError = e.error || e; }
  let webSearchCount = 0;
  for (const e of events){ if (e.type === 'agent.tool_use' && e.name === 'web_search') webSearchCount++; }
  return { pending: pending, agentRepliedAfter: agentRepliedAfter, lastAgentMsg: lastAgentMsg, sessionError: sessionError, webSearchCount: webSearchCount };
}
function extractText(msg){ if (!msg) return ''; const c = msg.content || []; return c.filter(function(b){ return b && b.type === 'text'; }).map(function(b){ return b.text || ''; }).join(''); }
let outcome = null, picked = null, analysis = null, statusObj = {}, consecErr = 0;
await sleep(1500);
while (true){
  if (remaining() <= 0){ outcome = 'deadline'; break; }
  try {
    const events = await getEvents();
    statusObj = await getStatus();
    consecErr = 0;
    analysis = analyze(events);
    const status = statusObj.status;
    if (analysis.sessionError){ outcome = 'terminated'; break; }
    if (status === 'terminated'){ outcome = 'terminated'; break; }
    if (status === 'idle'){
      if (analysis.pending.length > 0){ if (toolRound >= MAX_TOOL_ROUNDS){ outcome = 'max_rounds'; } else { outcome = 'pending_tool'; picked = analysis.pending[0]; } break; }
      if (analysis.agentRepliedAfter){ outcome = 'done'; break; }
    }
  } catch (e){
    consecErr++;
    if (consecErr >= MAX_CONSEC_ERRORS){ outcome = 'poll_error'; break; }
  }
  if (remaining() <= 0){ outcome = 'deadline'; break; }
  await sleep(POLL_INTERVAL_MS);
}
const finalText = extractText(analysis ? analysis.lastAgentMsg : null);
return [{ json: Object.assign({}, st, {
  outcome: outcome,
  pending_tool_id: picked ? picked.id : '',
  pending_tool_name: picked ? picked.name : '',
  pending_tool_input_json: picked ? JSON.stringify(picked.input || {}) : '',
  final_message_text: finalText,
  web_search_count: analysis ? analysis.webSearchCount : 0,
  duration_seconds: (statusObj && statusObj.stats) ? statusObj.stats.duration_seconds : null,
  session_usage_json: JSON.stringify((statusObj && statusObj.usage) ? statusObj.usage : {}),
  terminated_error_json: (analysis && analysis.sessionError) ? JSON.stringify(analysis.sessionError).slice(0,500) : ''
}) }];

const h = $json || {};
const status = h.status || 'failed';
const file_ids = Array.isArray(h.file_ids) ? h.file_ids : [];
const msg = h.message || 'Image tool returned no message.';
const text = JSON.stringify({ status: status, file_ids: file_ids, message: msg, count_uploaded: h.count_uploaded, count_failed: h.count_failed });
return [{ json: {
  tool_result_text: text,
  new_images_json: JSON.stringify(Array.isArray(h.images) ? h.images : []),
  new_warnings_json: JSON.stringify(Array.isArray(h.warnings) ? h.warnings : [])
} }];

const st = $('Poll Round').first().json;
const name = st.pending_tool_name || 'unknown';
const text = JSON.stringify({ status: 'failed', message: 'The tool "' + name + '" is not available. Proceed without it and inform the user if relevant.' });
return [{ json: {
  tool_result_text: text,
  new_images_json: '[]',
  new_warnings_json: JSON.stringify([{ source: 'managed-agents/unknown-tool', err: 'agent requested an unregistered custom tool: ' + name, severity: 'WARN' }])
} }];

const st = $('Poll Round').first().json;
const r = ($('Merge Result').first() || {}).json || {};
let images = []; try { images = JSON.parse(st.images_json || '[]'); } catch (e) {}
let warnings = []; try { warnings = JSON.parse(st.warnings_json || '[]'); } catch (e) {}
let ni = []; try { ni = JSON.parse(r.new_images_json || '[]'); } catch (e) {}
let nw = []; try { nw = JSON.parse(r.new_warnings_json || '[]'); } catch (e) {}
images = images.concat(ni);
warnings = warnings.concat(nw);
return [{ json: {
  session_id: st.session_id, anthropic_key: st.anthropic_key, file_map_json: st.file_map_json,
  deadline_epoch: st.deadline_epoch, tool_round: Number(st.tool_round || 0) + 1,
  images_json: JSON.stringify(images), warnings_json: JSON.stringify(warnings),
  agent_id: st.agent_id, model_id: st.model_id, impact: st.impact,
  clickup_task_id: st.clickup_task_id, caller_user_id: st.caller_user_id, process_type: st.process_type,
  triggered_by: st.triggered_by, invocation_type: st.invocation_type,
  user_message: '', input_images_json: ''
} }];

const st = $json;
let warnings = []; try { warnings = JSON.parse(st.warnings_json || '[]'); } catch (e) {}
let images = []; try { images = JSON.parse(st.images_json || '[]'); } catch (e) {}
let usage = {}; try { usage = JSON.parse(st.session_usage_json || '{}'); } catch (e) {}
const outcome = st.outcome;
let status = 'completed';
if (outcome === 'deadline'){ status = 'partial'; warnings.push({ source: 'managed-agents/session-deadline', err: 'Sesja agenta przekroczyla limit czasu (840s) — zwrocono wynik czesciowy', severity: 'WARN' }); }
else if (outcome === 'terminated'){ status = 'failed'; warnings.push({ source: 'managed-agents/session-error', err: 'Sesja zakonczona bledem: ' + (st.terminated_error_json || 'nieznany'), severity: 'WARN' }); }
else if (outcome === 'max_rounds'){ status = 'partial'; warnings.push({ source: 'managed-agents/max-tool-rounds', err: 'Osiagnieto limit rund narzedzia generate_image (12) — zwrocono wynik czesciowy', severity: 'WARN' }); }
else if (outcome === 'poll_error'){ status = 'partial'; warnings.push({ source: 'managed-agents/poll-error', err: 'Wielokrotne bledy odczytu zdarzen sesji — zwrocono wynik czesciowy', severity: 'WARN' }); }
const file_ids = images.map(function(im){ return im.file_id; }).filter(Boolean);
return [{ json: {
  status: status,
  output_message: st.final_message_text || '',
  files: images,
  file_ids: file_ids,
  usd_cost: null,
  usd_cost_stub: true,
  session_usage: usage,
  duration_seconds: (st.duration_seconds != null) ? st.duration_seconds : null,
  web_search_count: st.web_search_count || 0,
  model_used: st.model_id || '',
  agent_id: st.agent_id || '',
  session_id: st.session_id || '',
  impact: st.impact || '',
  clickup_task_id: st.clickup_task_id || '',
  warnings: warnings,
  failure_kind: '',
  outcome: outcome
} }];

const o = $json;
let do_alert = false, sev = 'WARN', msg = '', det = '';
const warnings = Array.isArray(o.warnings) ? o.warnings : [];
if (o.failure_kind){ do_alert = true; sev = 'CRITICAL'; msg = 'Sesja Managed Agents nie wystartowala (' + o.failure_kind + ') dla zadania ' + (o.clickup_task_id || '?'); det = warnings.map(function(w){ return (w.source || '') + ': ' + (w.err || ''); }).join(' | ').slice(0,1500); }
else if (warnings.length > 0){ do_alert = true; const hasCrit = warnings.some(function(w){ return w.severity === 'CRITICAL'; }); sev = hasCrit ? 'CRITICAL' : 'WARN'; msg = 'Sesja Managed Agents zakonczona z ostrzezeniami (' + warnings.length + ') [status: ' + (o.status || '?') + '] dla zadania ' + (o.clickup_task_id || '?'); det = warnings.map(function(w){ return (w.source || '') + ': ' + (w.err || ''); }).join(' | ').slice(0,1500); }
return [{ json: Object.assign({}, o, { do_alert: do_alert, _sev: sev, _msg: msg, _details: det }) }];
